using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using MC2Pack;
namespace Astera {
public sealed class MinecraftProfileArt {public string Path="",Background="",Character="",Icon="";}
sealed partial class LibraryForm {
 GameProfile minecraftSelection;string minecraftSelectionPath;List<GameProfile> minecraftChoices=new List<GameProfile>();bool scanningMinecraftProfiles;
 bool MinecraftSquaredSelected {get{return minecraftSelection!=null&&minecraftSelection.IsSquared;}}
 string MinecraftSelectedTitle {get{return MinecraftSquaredSelected?"Minecraft²":minecraftSelection==null||minecraftSelection.LoaderKind=="vanilla"?"Minecraft":minecraftSelection.Name;}}
 void EnsureMinecraftSelection(){string selected=store.Settings.Profile??"";if(selected==minecraftSelectionPath)return;minecraftSelectionPath=selected;minecraftSelection=null;if(!String.IsNullOrWhiteSpace(selected))try{minecraftSelection=Profiles.Read(selected);}catch(Exception error){AsteraDiagnostics.Write("Minecraft profile unavailable",new IOException(error.GetType().Name));}var art=MinecraftArt(false);if(art!=null&&!String.IsNullOrWhiteSpace(art.Icon))CacheCustomIcon(new CustomGame{Id="minecraft-icon",Icon=art.Icon});else if(minecraftSelection!=null&&!MinecraftSquaredSelected&&!String.IsNullOrWhiteSpace(minecraftSelection.Icon))CacheCustomIcon(new CustomGame{Id="minecraft-icon",Icon=minecraftSelection.Icon});}
 MinecraftProfileArt MinecraftArt(bool create){if(store.Settings.MinecraftArtwork==null)store.Settings.MinecraftArtwork=new List<MinecraftProfileArt>();string path=store.Settings.Profile??"";var item=store.Settings.MinecraftArtwork.FirstOrDefault(p=>p!=null&&String.Equals(p.Path,path,StringComparison.OrdinalIgnoreCase));if(item==null&&create&&!String.IsNullOrWhiteSpace(path)){item=new MinecraftProfileArt{Path=path};store.Settings.MinecraftArtwork.Add(item);}return item;}
 void RememberMinecraftLibrary(GameProfile profile){if(profile==null)return;if(profile.IsPrism){if(store.Settings.PrismLibraries==null)store.Settings.PrismLibraries=new List<string>();string data=String.IsNullOrWhiteSpace(profile.LauncherRoot)?store.Settings.PrismDataRoot:profile.LauncherRoot;if(!String.IsNullOrWhiteSpace(data)&&!store.Settings.PrismLibraries.Contains(data,StringComparer.OrdinalIgnoreCase))store.Settings.PrismLibraries.Add(data);}else{if(store.Settings.MinecraftLibraries==null)store.Settings.MinecraftLibraries=new List<string>();string parent=Path.GetDirectoryName(profile.Path);if(!store.Settings.MinecraftLibraries.Contains(parent,StringComparer.OrdinalIgnoreCase))store.Settings.MinecraftLibraries.Add(parent);}}
 string MinecraftBackground {get{var art=MinecraftArt(false);return art!=null&&!String.IsNullOrWhiteSpace(art.Background)?art.Background:MinecraftSquaredSelected?store.Settings.BackgroundMinecraft:"";}}
 string MinecraftCharacter {get{var art=MinecraftArt(false);return art!=null&&!String.IsNullOrWhiteSpace(art.Character)?art.Character:MinecraftSquaredSelected?store.Settings.CharacterMinecraft:"";}}
 Image MinecraftSelectedIcon(){var art=MinecraftArt(false);string path=art!=null&&!String.IsNullOrWhiteSpace(art.Icon)?art.Icon:minecraftSelection!=null&&!MinecraftSquaredSelected?minecraftSelection.Icon:"";Image image;return !String.IsNullOrWhiteSpace(path)&&customIcons.TryGetValue(path,out image)?image:MinecraftSquaredSelected?GameArtwork.MinecraftIcon:GameArtwork.VanillaMinecraftIcon;}
 void RefreshMinecraftPresentation(){RefreshMinecraftProfileStrip();if(!MinecraftSquaredSelected){updateReady=false;play.Text=String.IsNullOrWhiteSpace(store.Settings.Profile)?"SET UP":"PLAY";((AsteraButton)play).Symbol=ButtonSymbol.Play;check.Text="Profile settings";download.Enabled=install.Enabled=restore.Enabled=false;status.Text=minecraftSelection==null?"Choose a Minecraft instance":"Ready to play";notes.Text="Updates for this profile are managed by "+(minecraftSelection!=null&&minecraftSelection.IsPrism?"Prism Launcher":"its launcher")+". Minecraft² updates apply only to Minecraft² profiles.";releaseLabel.Text=minecraftSelection==null?"Choose a profile to get started.":"Ready to play";}ApplyBuiltinRunning();}
 void RefreshMinecraftProfileStrip(){if(modProfileStrip==null)return;modProfileStrip.Visible=true;modProfileChoose.ProfileName=minecraftSelection==null?"Choose profile":MinecraftSquaredSelected?"Minecraft²":minecraftSelection.Name;modProfileChoose.AccessibleName="Minecraft profile: "+modProfileChoose.ProfileName;modProfileChoose.Enabled=!busy;modProfileChoose.Invalidate();}
 async void ShowMinecraftProfileMenu(){if(busy||scanningMinecraftProfiles)return;scanningMinecraftProfiles=true;try{string data=String.IsNullOrWhiteSpace(store.Settings.PrismDataRoot)?PrismProfiles.DefaultData:store.Settings.PrismDataRoot;var choices=await Task.Run(delegate{var result=new List<GameProfile>();foreach(string root in new[]{Profiles.DefaultRoot}.Concat(store.Settings.MinecraftLibraries??new List<string>()).Where(p=>!String.IsNullOrWhiteSpace(p)).Distinct(StringComparer.OrdinalIgnoreCase))try{result.AddRange(Profiles.All(root));}catch(IOException){}catch(UnauthorizedAccessException){}foreach(string prism in new[]{data,PrismProfiles.DefaultData}.Concat(store.Settings.PrismLibraries??new List<string>()).Where(p=>!String.IsNullOrWhiteSpace(p)).Distinct(StringComparer.OrdinalIgnoreCase))try{foreach(var p in Profiles.All(PrismProfiles.InstanceDirectory(prism))){p.LauncherRoot=prism;if(!result.Any(x=>x.Path.Equals(p.Path,StringComparison.OrdinalIgnoreCase)))result.Add(p);}}catch(IOException){}catch(UnauthorizedAccessException){}if(minecraftSelection!=null&&!result.Any(p=>p.Path.Equals(minecraftSelection.Path,StringComparison.OrdinalIgnoreCase)))result.Add(minecraftSelection);return result.OrderBy(p=>p.Name,StringComparer.OrdinalIgnoreCase).ToList();});if(IsDisposed||GameKind!=0)return;minecraftChoices=choices;ClearLibraryMenu(modProfileMenu);foreach(var profile in choices){var selected=profile;var item=new ToolStripMenuItem(profile.ToString()){Checked=profile.Path.Equals(store.Settings.Profile,StringComparison.OrdinalIgnoreCase)};item.Click+=delegate{SelectMinecraftProfile(selected);};modProfileMenu.Items.Add(item);}if(choices.Count==0)modProfileMenu.Items.Add(new ToolStripMenuItem("No instances found"){Enabled=false});modProfileMenu.Items.Add(new ToolStripSeparator());modProfileMenu.Items.Add("Create vanilla in Prism…",null,async delegate{await CreateVanillaPrism();});modProfileMenu.Items.Add("Set up / link an instance…",null,delegate{ConfigureMinecraft();});modProfileMenu.Show(modProfileChoose,new Point(0,modProfileChoose.Height));}catch(Exception error){MessageBox.Show(this,error.Message,"Minecraft profiles");}finally{scanningMinecraftProfiles=false;}}
 void SelectMinecraftProfile(GameProfile profile){if(busy||profile==null||profile.Path.Equals(store.Settings.Profile,StringComparison.OrdinalIgnoreCase))return;ClearPrepared();feed=null;plan=null;updateReady=false;minecraftChannelBehind=false;RememberMinecraftLibrary(profile);store.Settings.Profile=profile.Path;if(profile.IsPrism&&!String.IsNullOrWhiteSpace(profile.LauncherRoot))store.Settings.PrismDataRoot=profile.LauncherRoot;store.Settings.MinecraftLauncher=profile.IsPrism?"prism":"curseforge";store.Save();minecraftSelectionPath=null;EnsureMinecraftSelection();SwitchGame();if(MinecraftSquaredSelected)CheckSelectedMinecraftProfile();}
 async void CheckSelectedMinecraftProfile(){await CheckMinecraft(false);}
 async Task CreateVanillaPrism(){if(busy)return;try{string data=String.IsNullOrWhiteSpace(store.Settings.PrismDataRoot)?PrismProfiles.DefaultData:store.Settings.PrismDataRoot;UpdateFeed release=null;await Work(delegate{release=new UpdateClient(channel.PublicKeyXml).Check(store.Settings.FeedUrl,cancellation.Token);},false);if(release==null||IsDisposed)return;var made=PrismProfiles.Create(data,release.Release,true);SelectMinecraftProfile(Profiles.Read(made.GameRoot));}catch(Exception error){MessageBox.Show(this,error.Message,"Create vanilla instance");}}
 void SetMinecraftArtwork(string path,bool character){var art=MinecraftArt(true);if(art==null)return;if(character)art.Character=path;else art.Background=path;}
 void ChooseMinecraftIcon(){using(var picker=new OpenFileDialog{Title="Choose this Minecraft profile's icon",Filter="PNG or GIF|*.png;*.gif",CheckFileExists=true}){if(picker.ShowDialog(this)!=DialogResult.OK)return;try{var art=MinecraftArt(true);if(art==null)return;using(var proof=ArtworkAnimation.Open(picker.FileName)){}art.Icon=picker.FileName;CacheCustomIcon(new CustomGame{Id="minecraft-icon",Icon=art.Icon});store.Save();games.Invalidate();}catch(Exception error){MessageBox.Show(this,error.Message,"Profile icon");}}}
 internal static ProcessStartInfo CurseForgeLaunchInfo(string profile){return CurseForgeLaunch.Resolve(profile);}
}
}
